const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
const BIRTH_NEIGHBOR_COUNT = 3;

const isAliveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
  const liveNeighbors = countLiveNeighbors(cell, liveCells);
  return contains(liveCells, cell)
    ? SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors)
    : liveNeighbors === BIRTH_NEIGHBOR_COUNT;
};

